//! Derivatives of calibrated states and their downstream observations.
//!
//! A converged calibration connects independent market parameters to solved
//! states through residual equations. This module uses the residual Jacobians
//! and optional Hessians generated by a compiled function to calculate that
//! connection, then applies it to the requested observations.

use nalgebra::DMatrix;

use super::{
    compiledfunction::CompiledFunction, compileerror::CompileError,
    derivativeorder::DerivativeOrder,
};

/// AD derivatives through a converged calibration, without differentiating solver iterations.
///
/// Capture one [`CompiledFunction`] with inputs `[states, parameters]` and
/// outputs `[residuals, observations]`. There must be one residual per state.
/// At the supplied root, this solves `F_x x_q = -F_q`, then composes each
/// observation with that state map. Second-order compilation also includes
/// `x_qq`; omitting it would lose calibration curvature and cross terms.
///
/// Matrices use row-major order. A Hessian has one `parameters * parameters`
/// block per state or observation. First-order functions allocate no Hessians.
pub struct ImplicitDerivatives {
    states: usize,
    parameters: usize,
    observations: usize,
    state_jacobian: Vec<f64>,
    state_hessians: Option<Vec<f64>>,
    jacobian: Vec<f64>,
    hessians: Option<Vec<f64>>,
}

impl ImplicitDerivatives {
    /// Differentiates a locally nonsingular calibration at its converged state.
    ///
    /// `inputs[..states]` must already solve the first `states` outputs. This
    /// method does not solve or check residual convergence: residual scaling
    /// and solver tolerances belong to the caller. Discrete active constraints
    /// must be represented by the captured residuals, with the desired branch
    /// convention. All remaining inputs are independent parameters.
    ///
    /// # Errors
    /// Rejects incompatible dimensions, nonfinite derivatives, a singular
    /// state Jacobian, and errors from the compiled numerical function.
    pub fn evaluate(
        function: &CompiledFunction,
        inputs: &[f64],
        states: usize,
    ) -> Result<Self, CompileError> {
        let width = function.input_count();
        let outputs = function.output_count();
        if states == 0 || states > width || states > outputs {
            return Err(CompileError::InvalidGraph(
                "implicit differentiation needs one residual per state and inputs [states, parameters]"
                    .into(),
            ));
        }
        let parameters = width - states;
        let observations = outputs - states;
        let mut values = vec![0.0; outputs];
        let mut partials = vec![0.0; outputs * width];
        let mut second_partials = if function.derivative_order() == DerivativeOrder::Second {
            Some(vec![0.0; outputs * width * width])
        } else {
            None
        };
        if let Some(hessians) = &mut second_partials {
            function.values_jacobian_hessians(inputs, &mut values, &mut partials, hessians)?;
        } else {
            function.values_and_jacobian(inputs, &mut values, &mut partials)?;
        }
        if partials.iter().any(|value| !value.is_finite())
            || second_partials
                .as_ref()
                .is_some_and(|values| values.iter().any(|value| !value.is_finite()))
        {
            return Err(CompileError::InvalidGraph(
                "nonfinite implicit calibration derivatives".into(),
            ));
        }
        let state_partials =
            DMatrix::from_fn(states, states, |row, column| partials[row * width + column]);
        let negative_parameter_partials = DMatrix::from_fn(states, parameters, |row, column| {
            -partials[row * width + states + column]
        });
        let lu = state_partials.lu();
        let state_jacobian = lu.solve(&negative_parameter_partials).ok_or_else(|| {
            CompileError::InvalidGraph("singular implicit calibration Jacobian".into())
        })?;
        let tangent = DMatrix::from_fn(width, parameters, |row, column| {
            if row < states {
                state_jacobian[(row, column)]
            } else {
                f64::from(row - states == column)
            }
        });
        let observation_partials = DMatrix::from_fn(observations, width, |row, column| {
            partials[(states + row) * width + column]
        });
        let jacobian = &observation_partials * &tangent;
        let (state_hessians, hessians) = if let Some(second_partials) = second_partials {
            let contracted = contract_hessians(&second_partials, &tangent);
            let rhs = -contracted.rows(0, states).into_owned();
            let state_hessians = lu.solve(&rhs).ok_or_else(|| {
                CompileError::InvalidGraph("singular implicit calibration Jacobian".into())
            })?;
            let observation_hessians = contracted.rows(states, observations)
                + observation_partials.columns(0, states) * &state_hessians;
            (
                Some(row_major(&state_hessians)),
                Some(row_major(&observation_hessians)),
            )
        } else {
            (None, None)
        };
        let result = Self {
            states,
            parameters,
            observations,
            state_jacobian: row_major(&state_jacobian),
            state_hessians,
            jacobian: row_major(&jacobian),
            hessians,
        };
        if result
            .state_jacobian
            .iter()
            .chain(&result.jacobian)
            .chain(result.state_hessians.iter().flatten())
            .chain(result.hessians.iter().flatten())
            .any(|value| !value.is_finite())
        {
            return Err(CompileError::InvalidGraph(
                "nonfinite implicit calibration solve".into(),
            ));
        }
        Ok(result)
    }

    /// Returns the number of calibrated states and corresponding residuals.
    #[must_use]
    pub const fn state_count(&self) -> usize {
        self.states
    }

    /// Returns the number of independent parameter coordinates.
    #[must_use]
    pub const fn parameter_count(&self) -> usize {
        self.parameters
    }

    /// Returns the number of observations following the residual outputs.
    #[must_use]
    pub const fn observation_count(&self) -> usize {
        self.observations
    }

    /// Returns the state derivatives with respect to parameters in row-major order.
    #[must_use]
    pub fn state_jacobian(&self) -> &[f64] {
        &self.state_jacobian
    }

    /// Returns each state's parameter-space Hessian when second-order derivatives were compiled.
    #[must_use]
    pub fn state_hessians(&self) -> Option<&[f64]> {
        self.state_hessians.as_deref()
    }

    /// Returns the total observation derivatives with respect to parameters in row-major order.
    #[must_use]
    pub fn jacobian(&self) -> &[f64] {
        &self.jacobian
    }

    /// Returns the observation Hessians, including calibration curvature, when available.
    #[must_use]
    pub fn hessians(&self) -> Option<&[f64]> {
        self.hessians.as_deref()
    }
}

/// Maps residual curvature through state/parameter tangents without losing mixed terms.
fn contract_hessians(partials: &[f64], tangent: &DMatrix<f64>) -> DMatrix<f64> {
    let width = tangent.nrows();
    let parameters = tangent.ncols();
    let outputs = partials.len() / (width * width);
    let mut contracted = DMatrix::zeros(outputs, parameters * parameters);
    for (output, partials) in partials.chunks_exact(width * width).enumerate() {
        let hessian = DMatrix::from_row_slice(width, width, partials);
        let composed = tangent.transpose() * hessian * tangent;
        for row in 0..parameters {
            for column in 0..parameters {
                contracted[(output, row * parameters + column)] = composed[(row, column)];
            }
        }
    }
    contracted
}

/// Copies a matrix into the row-major layout used by native derivative buffers.
fn row_major(matrix: &DMatrix<f64>) -> Vec<f64> {
    (0..matrix.nrows())
        .flat_map(|row| (0..matrix.ncols()).map(move |column| matrix[(row, column)]))
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Checks inclusion of calibration curvature in observation hessians.
    #[test]
    fn includes_calibration_curvature_in_observation_hessians() -> Result<(), CompileError> {
        // x = sqrt(q), observation x^3 + q*x = 2*q^(3/2).
        let function =
            CompiledFunction::try_trace_with_order(&[2.0, 4.0], DerivativeOrder::Second, |v| {
                Ok::<_, &str>(vec![v[0] * v[0] - v[1], v[0].powf(3.0) + v[0] * v[1]])
            })?;
        for x in [0.5, 2.0, 5.0] {
            let result = ImplicitDerivatives::evaluate(&function, &[x, x * x], 1)?;
            assert!((result.state_jacobian()[0] - 0.5 / x).abs() < 1e-12);
            assert!((result.state_hessians().unwrap()[0] + 0.25 / x.powi(3)).abs() < 1e-12);
            assert!((result.jacobian()[0] - 3.0 * x).abs() < 1e-12);
            assert!((result.hessians().unwrap()[0] - 1.5 / x).abs() < 1e-12);
        }
        Ok(())
    }

    /// Checks coupled states and cross parameter curvature match closed form.
    #[test]
    fn coupled_states_and_cross_parameter_curvature_match_closed_form() -> Result<(), CompileError>
    {
        // x0 = q0*q1, x1 = x0 + q1^2. This triangular residual system is
        // nonlinear in both state and parameters; observation = x0*x1.
        let function = CompiledFunction::try_trace_with_order(
            &[6.0, 15.0, 2.0, 3.0],
            DerivativeOrder::Second,
            |v| {
                Ok::<_, &str>(vec![
                    v[0] - v[2] * v[3],
                    v[1] - v[0] - v[3] * v[3],
                    v[0] * v[1],
                ])
            },
        )?;
        let result = ImplicitDerivatives::evaluate(&function, &[6.0, 15.0, 2.0, 3.0], 2)?;
        assert_eq!(result.state_jacobian(), [3.0, 2.0, 3.0, 8.0]);
        assert_eq!(
            result.state_hessians().unwrap(),
            [0.0, 1.0, 1.0, 0.0, 0.0, 1.0, 1.0, 2.0]
        );
        assert_eq!(result.jacobian(), [63.0, 78.0]);
        assert_eq!(result.hessians().unwrap(), [18.0, 51.0, 51.0, 44.0]);
        Ok(())
    }

    /// Checks inclusion of mixed state parameter residual derivatives.
    #[test]
    fn includes_mixed_state_parameter_residual_derivatives() -> Result<(), CompileError> {
        // (q + 1)*x = q^2, so x'' = 2/(q + 1)^3.
        let function = CompiledFunction::try_trace_with_order(
            &[4.0 / 3.0, 2.0],
            DerivativeOrder::Second,
            |v| Ok::<_, &str>(vec![(v[1] + 1.0) * v[0] - v[1] * v[1]]),
        )?;
        let result = ImplicitDerivatives::evaluate(&function, &[4.0 / 3.0, 2.0], 1)?;
        assert!((result.state_jacobian()[0] - 8.0 / 9.0).abs() < 1e-12);
        assert!((result.state_hessians().unwrap()[0] - 2.0 / 27.0).abs() < 1e-12);
        assert_eq!(result.observation_count(), 0);
        Ok(())
    }

    /// Checks first order has no hessian and invalid systems fail.
    #[test]
    fn first_order_has_no_hessian_and_invalid_systems_fail() -> Result<(), CompileError> {
        let function = CompiledFunction::trace(&[2.0, 4.0], |v| vec![v[0] * v[0] - v[1], v[0]])?;
        let first = ImplicitDerivatives::evaluate(&function, &[2.0, 4.0], 1)?;
        assert!(first.state_hessians().is_none());
        assert!(first.hessians().is_none());
        assert!(ImplicitDerivatives::evaluate(&function, &[2.0, 4.0], 0).is_err());
        assert!(ImplicitDerivatives::evaluate(&function, &[2.0, 4.0], 3).is_err());
        assert!(ImplicitDerivatives::evaluate(&function, &[0.0, 0.0], 1).is_err());
        assert!(ImplicitDerivatives::evaluate(&function, &[2.0], 1).is_err());
        Ok(())
    }
}
